import itertools
data=open('/workspace/output','rb').read().strip()
print(len(data), data)
res=[]
for perm in itertools.permutations(range(8)):
    # inverse: out bit perm[i] comes from in bit i
    tr=[]
    for b in data:
        # map b bits: out bit i = in bit perm[i]; invert
        v=0
        for i in range(8):
            if (b>>i)&1: v|=1<<perm[i]
        tr.append(v)
    for k in range(256):
        s=bytes(x^k for x in tr)
        if s.startswith(b'flag{') or s.startswith(b'FLAG{'):
            res.append((perm,k,s))
print(len(res))
for r in res[:10]: print(r)
# also simple xor/add checks
for k in range(256):
    s=bytes(x^k for x in data)
    if b'flag' in s or b'{' in s: print('xor',k,s)
    s2=bytes((x-k)%256 for x in data)
    if s2.startswith(b'flag'): print('sub',k,s2)

