import itertools
data=open('/workspace/output','rb').read().strip()
def check(s):
    return s.startswith(b'flag{') or s.startswith(b'FLAG{') or b'flag' in s.lower()
found=[]
# position-dependent xor/add/sub
for mode in ['xi','ai','si','xi1','ai1']:
    for k in range(256):
        out=[]
        for i,c in enumerate(data):
            if mode=='xi': v=c^((i+k)&255)
            elif mode=='ai': v=(c-((i+k)&255))&255
            elif mode=='si': v=(c+((i+k)&255))&255
            elif mode=='xi1': v=c^(((i*k))&255)
            else: v=(c-(i*k))&255
            out.append(v)
        s=bytes(out)
        if check(s): found.append((mode,k,s))
print('pos',found[:5])
# 2-bit symbol permutations per group, with xor key
hits=[]
for p in itertools.permutations(range(4)):
    for k in range(256):
        out=[]
        for c in data:
            v=0
            for g in range(4):
                sym=(c>>(2*g))&3
                v|=p[sym]<<(2*g)
            out.append(v^k)
        s=bytes(out)
        if check(s): hits.append((p,k,s))
print('sym',hits[:5])
# 2-bit nibble swap / bit-pair order reversal combos
for k in range(256):
    s=bytes(c^k for c in data)
    if all(32<=x<127 for x in s) and s.count(b'{')>0: print('xor',k,s)

